// Package postgres implements the candidates persistence port against
// PostgreSQL. The adapter owns the *pgxpool.Pool so it can run the
// atomic language-replace in a single transaction; the *db.Queries
// generated by sqlc is scoped per-call (db.New(pool) or db.New(tx)).
package postgres

import (
	"context"
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"

	catalog "github.com/aldrichcode45/peopleflow-vacantes/internal/shared/languages"

	"github.com/aldrichcode45/peopleflow-vacantes/internal/db"
	"github.com/aldrichcode45/peopleflow-vacantes/internal/features/candidates/domain/entities"
	candidaterepositories "github.com/aldrichcode45/peopleflow-vacantes/internal/features/candidates/domain/repositories"
	"github.com/aldrichcode45/peopleflow-vacantes/internal/features/candidates/domain/valueobjects"
	geo "github.com/aldrichcode45/peopleflow-vacantes/internal/features/geo/domain"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"
)

// CandidateRepository is the PostgreSQL adapter for
// candidaterepositories.CandidateRepository. It holds a connection pool
// because the atomic language-replace needs to manage its own
// transaction; non-tx paths borrow a Queries from db.New(pool).
type CandidateRepository struct {
	pool *pgxpool.Pool
}

// NewCandidateRepository wraps the connection pool. The pool is
// retained so the adapter can open transactions directly via
// pool.Begin(ctx).
func NewCandidateRepository(pool *pgxpool.Pool) *CandidateRepository {
	return &CandidateRepository{pool: pool}
}

// Compile-time assertion that the adapter satisfies the domain port.
// A future port change here surfaces as a build error, never a runtime
// "method missing" panic.
var _ candidaterepositories.CandidateRepository = (*CandidateRepository)(nil)

// UpsertProfile performs the idempotent INSERT ... ON CONFLICT (user_id)
// DO UPDATE on candidate_profiles and returns the persisted row. The
// search_vector column is a STORED generated column owned by Postgres
// and MUST NOT be touched from application code (design decision #9).
func (r *CandidateRepository) UpsertProfile(ctx context.Context, profile *entities.CandidateProfile) (*entities.CandidateProfile, error) {
	tx, err := r.pool.Begin(ctx)
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback(ctx) }()
	q := db.New(tx)
	row, err := q.UpsertCandidateProfile(ctx, buildUpsertParams(profile))
	if err != nil {
		return nil, mapCreateError(err)
	}
	if err = q.DeleteCandidateEducations(ctx, row.UserID); err != nil {
		return nil, err
	}
	if profile.EducationLevel != nil {
		err = q.InsertLegacyCandidateEducation(ctx, db.InsertLegacyCandidateEducationParams{UserID: row.UserID, Level: profile.EducationLevel.String(), Field: textPtrToPgText(profile.FieldOfStudy)})
		if err != nil {
			return nil, err
		}
	}
	out, err := profileWithEducation(ctx, q, row)
	if err != nil {
		return nil, err
	}
	if err = tx.Commit(ctx); err != nil {
		return nil, err
	}
	return out, nil
}

// GetProfileByUserID fetches the caller's profile. The pgx "no rows"
// sentinel is translated to entities.ErrProfileNotFound so the HTTP
// layer can dispatch on errors.Is without importing pgx.
func (r *CandidateRepository) GetProfileByUserID(ctx context.Context, userID uuid.UUID) (*entities.CandidateProfile, error) {
	row, err := db.New(r.pool).GetCandidateProfileByUserID(ctx, userID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, entities.ErrProfileNotFound
		}
		return nil, err
	}
	return profileWithEducation(ctx, db.New(r.pool), row)
}

func profileWithEducation(ctx context.Context, q *db.Queries, row db.CandidateProfile) (*entities.CandidateProfile, error) {
	out, err := toEntity(row)
	if err != nil {
		return nil, err
	}
	education, err := q.GetLegacyCandidateEducation(ctx, row.UserID)
	if errors.Is(err, pgx.ErrNoRows) {
		return out, nil
	}
	if err != nil {
		return nil, err
	}
	level, err := valueobjects.ParseEducationLevel(education.Level)
	if err != nil {
		return nil, err
	}
	out.EducationLevel = &level
	out.FieldOfStudy = pgTextToTextPtr(education.Field)
	return out, nil
}

// ListLanguagesByUserID returns the caller's candidate_languages rows
// ordered by language. An empty list comes back as a non-nil empty
// slice so the JSON encoder produces "[]" rather than "null".
func (r *CandidateRepository) ListLanguagesByUserID(ctx context.Context, userID uuid.UUID) ([]entities.Language, error) {
	rows, err := db.New(r.pool).ListCandidateLanguagesByUserID(ctx, userID)
	if err != nil {
		return nil, err
	}
	out := make([]entities.Language, 0, len(rows))
	for _, row := range rows {
		level, err := valueobjects.ParseCefrLevel(row.Level)
		if err != nil {
			// A row that survived a past migration with a bad level is
			// a real data-integrity issue; fail loud rather than
			// silently substituting UnknownCefrLevel.
			return nil, fmt.Errorf("invalid CEFR level in candidate_languages: %w", err)
		}
		name, ok := catalog.Lookup(row.Code)
		if !ok {
			return nil, fmt.Errorf("unknown stored language code %q", row.Code)
		}
		// Keep the old API's spelling where one name can represent the code.
		if row.LegacyName != "" {
			name = row.LegacyName
		}
		out = append(out, entities.Language{Name: name, Level: level})
	}
	return out, nil
}

// ReplaceLanguagesByUserID atomically replaces the user's full
// language list. The delete + N inserts run in one pgx.Tx so a
// duplicate (or any other error) rolls the whole operation back,
// leaving the original list intact. The composite PK (user_id,
// language) is the second line of defense after the use case's
// duplicate check.
func (r *CandidateRepository) ReplaceLanguagesByUserID(ctx context.Context, userID uuid.UUID, languages []entities.Language) error {
	tx, err := r.pool.Begin(ctx)
	if err != nil {
		return fmt.Errorf("begin tx: %w", err)
	}
	// defer Rollback is a no-op after Commit succeeds; on any error
	// path below it sends the ROLLBACK to the server.
	defer func() { _ = tx.Rollback(ctx) }()

	queries := db.New(tx)
	if err := queries.DeleteCandidateLanguagesByUserID(ctx, userID); err != nil {
		return fmt.Errorf("delete existing languages: %w", err)
	}

	if err := queries.DeleteLegacyCandidateLanguageNames(ctx, userID); err != nil {
		return err
	}
	for _, l := range languages {
		code, ok := catalog.CodeForLegacyName(l.Name)
		if !ok {
			return fmt.Errorf("unknown legacy language name %q", l.Name)
		}
		if err := queries.InsertCandidateLanguage(ctx, db.InsertCandidateLanguageParams{
			UserID: userID,
			Code:   code,
			Level:  l.Level.String(),
		}); err != nil {
			// The unique PK (user_id, language) catches any duplicate
			// the use case let through; surface a domain sentinel so
			// the HTTP layer can map to 400.
			return mapCreateError(err)
		}
		if err := queries.InsertLegacyCandidateLanguageName(ctx, db.InsertLegacyCandidateLanguageNameParams{UserID: userID, Language: l.Name, Level: l.Level.String(), Code: pgtype.Text{String: code, Valid: true}}); err != nil {
			return err
		}
	}

	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("commit tx: %w", err)
	}
	return nil
}

// buildUpsertParams translates the entity into the sqlc parameter
// struct. Every optional field becomes an invalid pgtype (SQL NULL)
// when the entity pointer is nil so the DB CHECK constraints see the
// same shape the domain validation produced. The reserved cv_s3_key
// column is deliberately absent: the candidate-API write path never
// writes it, so a preexisting reserved value survives every upsert.
func buildUpsertParams(p *entities.CandidateProfile) db.UpsertCandidateProfileParams {
	var birthDate pgtype.Date
	if p.BirthDate != nil {
		birthDate = pgtype.Date{Time: *p.BirthDate, Valid: true}
	}
	var country, state, municipality pgtype.Text
	if p.Location != nil {
		country = locationText(p.Location.Country)
		state = locationText(p.Location.State)
		municipality = locationText(p.Location.Municipality)
	}
	return db.UpsertCandidateProfileParams{
		UserID:               uuid.MustParse(p.UserID),
		Phone:                textPtrToPgText(p.Phone),
		LinkedinUrl:          textPtrToPgText(p.LinkedInURL),
		PortfolioUrl:         textPtrToPgText(p.PortfolioURL),
		ProfessionalTitle:    textPtrToPgText(p.ProfessionalTitle),
		CurrentCompany:       textPtrToPgText(p.CurrentCompany),
		YearsOfExperience:    legacyYearsToNumeric(p.YearsOfExperience),
		ProfileSummary:       textPtrToPgText(p.ProfileSummary),
		BirthDate:            birthDate,
		CountryCode:          country,
		StateCode:            state,
		MunicipalityCode:     municipality,
		Skills:               p.Skills,
		CurrentSalaryGross:   intPtrToInt4(p.CurrentSalaryGross),
		CurrentSalaryNet:     intPtrToInt4(p.CurrentSalaryNet),
		ExpectedSalary:       intPtrToInt4(p.ExpectedSalary),
		SalaryCurrency:       p.SalaryCurrency,
		ExpectedSalaryPeriod: salaryPeriodToPgText(p.ExpectedSalaryPeriod),
	}
}

// toEntity rebuilds the domain entity from a sqlc row. VOs are
// reconstructed via their parsers so unrecognized values fail loudly
// instead of silently producing a zero-valued aggregate.
func toEntity(row db.CandidateProfile) (*entities.CandidateProfile, error) {
	years, err := numericToLegacyYears(row.YearsOfExperience)
	if err != nil {
		return nil, err
	}

	var period *valueobjects.SalaryPeriod
	if row.ExpectedSalaryPeriod.Valid {
		parsed, err := valueobjects.ParseSalaryPeriod(row.ExpectedSalaryPeriod.String)
		if err != nil {
			return nil, err
		}
		period = &parsed
	}

	var location *geo.Value
	if row.CountryCode.Valid {
		location = &geo.Value{Country: row.CountryCode.String, State: row.StateCode.String, Municipality: row.MunicipalityCode.String}
	}
	return &entities.CandidateProfile{
		UserID:               row.UserID.String(),
		Phone:                pgTextToTextPtr(row.Phone),
		LinkedInURL:          pgTextToTextPtr(row.LinkedinUrl),
		PortfolioURL:         pgTextToTextPtr(row.PortfolioUrl),
		ProfessionalTitle:    pgTextToTextPtr(row.ProfessionalTitle),
		CurrentCompany:       pgTextToTextPtr(row.CurrentCompany),
		YearsOfExperience:    years,
		ProfileSummary:       pgTextToTextPtr(row.ProfileSummary),
		BirthDate:            pgDateToTimePtr(row.BirthDate),
		Location:             location,
		Skills:               row.Skills,
		CurrentSalaryGross:   int4ToIntPtr(row.CurrentSalaryGross),
		CurrentSalaryNet:     int4ToIntPtr(row.CurrentSalaryNet),
		ExpectedSalary:       int4ToIntPtr(row.ExpectedSalary),
		SalaryCurrency:       row.SalaryCurrency,
		ExpectedSalaryPeriod: period,
		CVS3Key:              pgTextToTextPtr(row.CvS3Key),
		CreatedAt:            pgTimestamptzToTime(row.CreatedAt),
		UpdatedAt:            pgTimestamptzToTime(row.UpdatedAt),
	}, nil
}

// --- pgtype ↔ Go pointer helpers ----------------------------------------

func locationText(s string) pgtype.Text { return pgtype.Text{String: s, Valid: s != ""} }

func textPtrToPgText(s *string) pgtype.Text {
	if s == nil {
		return pgtype.Text{}
	}
	return pgtype.Text{String: *s, Valid: true}
}

func pgTextToTextPtr(t pgtype.Text) *string {
	if !t.Valid {
		return nil
	}
	v := t.String
	return &v
}

// Decimal storage is decoded as text; only the legacy HTTP projection truncates.
func numericToLegacyYears(n pgtype.Numeric) (*int, error) {
	if !n.Valid {
		return nil, nil
	}
	value, err := n.Value()
	if err != nil {
		return nil, err
	}
	text, ok := value.(string)
	if !ok {
		return nil, fmt.Errorf("invalid numeric years")
	}
	integer, _, _ := strings.Cut(text, ".")
	years, err := strconv.Atoi(integer)
	if err != nil {
		return nil, err
	}
	return &years, nil
}

func legacyYearsToNumeric(years *int) pgtype.Numeric {
	var n pgtype.Numeric
	if years != nil {
		_ = n.Scan(strconv.Itoa(*years))
	}
	return n
}

func intPtrToInt4(i *int) pgtype.Int4 {
	if i == nil {
		return pgtype.Int4{}
	}
	return pgtype.Int4{Int32: int32(*i), Valid: true}
}

func int4ToIntPtr(i pgtype.Int4) *int {
	if !i.Valid {
		return nil
	}
	v := int(i.Int32)
	return &v
}

func pgDateToTimePtr(d pgtype.Date) *time.Time {
	if !d.Valid {
		return nil
	}
	v := d.Time
	return &v
}

func pgTimestamptzToTime(t pgtype.Timestamptz) time.Time {
	if !t.Valid {
		return time.Time{}
	}
	return t.Time
}

func salaryPeriodToPgText(s *valueobjects.SalaryPeriod) pgtype.Text {
	if s == nil {
		return pgtype.Text{}
	}
	return pgtype.Text{String: s.String(), Valid: true}
}

// mapCreateError translates Postgres constraint violations into domain
// sentinels so the HTTP layer can return 4xx instead of leaking 500s
// for client errors. Mirrors the companies adapter's contract.
//
//   - pgx.ErrNoRows → ErrProfileNotFound (Get path)
//   - 23505 (any UNIQUE collision) → ErrDuplicateLanguage
//   - anything else → pass through unchanged
//
// The (user_id, language) composite PK on candidate_languages is the
// only UNIQUE constraint this adapter can trip. The candidate_profiles
// PK on user_id cannot collide under ON CONFLICT DO UPDATE.
func mapCreateError(err error) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, pgx.ErrNoRows) {
		return entities.ErrProfileNotFound
	}
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) && pgErr.Code == "23505" { // unique_violation
		return entities.ErrDuplicateLanguage
	}
	return err
}
